        ["log.appIdRemoved"] = new[] { "AppID manual quitado de {0}.", "Manual AppID removed from {0}.", "AppID manual removido de {0}.", "AppID manuel retiré de {0}.", "Manuelle AppID von {0} entfernt.", "Ручной AppID для {0} удалён.", "已移除 {0} 的手动 AppID。", "{0} の手動 AppID を削除しました。" },
        ["log.appIdInvalid"] = new[] { "\"{0}\" no es un AppID válido: debe ser solo números.", "\"{0}\" is not a valid AppID: it must contain only numbers.", "\"{0}\" não é um AppID válido: deve conter só números.", "« {0} » n'est pas un AppID valide : il ne doit contenir que des chiffres.", "„{0}“ ist keine gültige AppID: Sie darf nur Ziffern enthalten.", "«{0}» — неверный AppID: он должен состоять только из цифр.", "“{0}”不是有效的 AppID：只能包含数字。", "「{0}」は有効な AppID ではありません。数字のみで入力してください。" },
        ["log.appIdSet"] = new[] { "AppID {0} asignado a {1}.", "AppID {0} set for {1}.", "AppID {0} definido para {1}.", "AppID {0} défini pour {1}.", "AppID {0} für {1} festgelegt.", "AppID {0} назначен для {1}.", "已为 {1} 设置 AppID {0}。", "{1} に AppID {0} を設定しました。" },
        ["log.configSaveFail"] = new[] { "No se pudo guardar la configuración: {0}", "Could not save the configuration: {0}", "Não foi possível salvar a configuração: {0}", "Impossible d'enregistrer la configuration : {0}", "Konfiguration konnte nicht gespeichert werden: {0}", "Не удалось сохранить настройки: {0}", "无法保存配置：{0}", "設定を保存できませんでした：{0}" },
        ["log.openFail"] = new[] { "No se pudo abrir {0}: {1}", "Could not open {0}: {1}", "Não foi possível abrir {0}: {1}", "Impossible d'ouvrir {0} : {1}", "{0} konnte nicht geöffnet werden: {1}", "Не удалось открыть {0}: {1}", "无法打开 {0}：{1}", "{0} を開けませんでした：{1}" },

        // ---------------------------------------------------------------- errores
        ["err.noWrite"] = new[] { "Windows no permite escribir en esa carpeta. Si el juego está en \"Archivos de programa\", abre la app como administrador o mueve el juego a otra carpeta.", "Windows doesn't allow writing to that folder. If the game is in \"Program Files\", run the app as administrator or move the game to another folder.", "O Windows não permite gravar nessa pasta. Se o jogo estiver em \"Arquivos de Programas\", abra o app como administrador ou mova o jogo para outra pasta.", "Windows n'autorise pas l'écriture dans ce dossier. Si le jeu est dans « Program Files », lancez l'app en administrateur ou déplacez le jeu.", "Windows erlaubt kein Schreiben in diesen Ordner. Liegt das Spiel unter „Programme“, starte die App als Administrator oder verschiebe das Spiel.", "Windows не разрешает запись в эту папку. Если игра в «Program Files», запустите приложение от имени администратора или переместите игру.", "Windows 不允许写入该文件夹。如果游戏位于“Program Files”中，请以管理员身份运行应用，或将游戏移到其他文件夹。", "Windows がこのフォルダーへの書き込みを許可していません。ゲームが「Program Files」にある場合は、管理者としてアプリを実行するか、ゲームを別のフォルダーに移動してください。" },
        ["err.dirGone"] = new[] { "La carpeta ya no existe (¿se movió o desinstaló el juego?).", "The folder no longer exists (was the game moved or uninstalled?).", "A pasta não existe mais (o jogo foi movido ou desinstalado?).", "Le dossier n'existe plus (le jeu a-t-il été déplacé ou désinstallé ?).", "Der Ordner existiert nicht mehr (wurde das Spiel verschoben oder deinstalliert?).", "Папка больше не существует (игру переместили или удалили?).", "文件夹已不存在（游戏是否已移动或卸载？）。", "フォルダーが存在しません（ゲームを移動またはアンインストールしましたか？）。" },
        ["err.pathLong"] = new[] { "La ruta es demasiado larga para Windows.", "The path is too long for Windows.", "O caminho é longo demais para o Windows.", "Le chemin est trop long pour Windows.", "Der Pfad ist für Windows zu lang.", "Путь слишком длинный для Windows.", "路径对 Windows 来说太长。", "パスが Windows には長すぎます。" },
        ["err.io"] = new[] { "Error de disco o archivo en uso: {0}", "Disk error or file in use: {0}", "Erro de disco ou arquivo em uso: {0}", "Erreur disque ou fichier utilisé : {0}", "Datenträgerfehler oder Datei in Verwendung: {0}", "Ошибка диска или файл занят: {0}", "磁盘错误或文件正在使用：{0}", "ディスクエラー、またはファイルが使用中です：{0}" },

        // ---------------------------------------------------------------- Hydra y bibliotecas
        ["hy.notFound"] = new[] { "No encontré los datos de Hydra en %AppData%. ¿Está instalado Hydra Launcher?", "I couldn't find Hydra's data in %AppData%. Is Hydra Launcher installed?", "Não encontrei os dados do Hydra em %AppData%. O Hydra Launcher está instalado?", "Données de Hydra introuvables dans %AppData%. Hydra Launcher est-il installé ?", "Keine Hydra-Daten in %AppData% gefunden. Ist Hydra Launcher installiert?", "Не найдены данные Hydra в %AppData%. Hydra Launcher установлен?", "在 %AppData% 中找不到 Hydra 的数据。是否已安装 Hydra Launcher？", "%AppData% に Hydra のデータが見つかりません。Hydra Launcher はインストールされていますか？" },
        ["hy.downloads"] = new[] { "Hydra usa por defecto la carpeta Descargas; la añado como biblioteca.", "Hydra uses the Downloads folder by default; adding it as a library.", "O Hydra usa a pasta Downloads por padrão; vou adicioná-la como biblioteca.", "Hydra utilise le dossier Téléchargements par défaut ; je l'ajoute comme bibliothèque.", "Hydra verwendet standardmäßig den Download-Ordner; ich füge ihn als Bibliothek hinzu.", "По умолчанию Hydra использует папку «Загрузки»; добавляю её как библиотеку.", "Hydra 默认使用“下载”文件夹；已将其添加为游戏库。", "Hydra は既定でダウンロードフォルダーを使います。ライブラリとして追加します。" },
        ["lib.missing"] = new[] { "La biblioteca \"{0}\" no existe o el disco no está conectado. Se salta.", "Library \"{0}\" doesn't exist or the drive isn't connected. Skipping.", "A biblioteca \"{0}\" não existe ou o disco não está conectado. Pulando.", "La bibliothèque « {0} » n'existe pas ou le disque n'est pas connecté. Ignorée.", "Bibliothek „{0}“ existiert nicht oder das Laufwerk ist nicht verbunden. Wird übersprungen.", "Библиотека «{0}» не существует или диск не подключён. Пропускаю.", "游戏库“{0}”不存在或磁盘未连接，已跳过。", "ライブラリ「{0}」が存在しないか、ドライブが接続されていません。スキップします。" },
        ["lib.readFail"] = new[] { "No se pudo leer \"{0}\": {1}", "Could not read \"{0}\": {1}", "Não foi possível ler \"{0}\": {1}", "Impossible de lire « {0} » : {1}", "„{0}“ konnte nicht gelesen werden: {1}", "Не удалось прочитать «{0}»: {1}", "无法读取“{0}”：{1}", "「{0}」を読み込めませんでした：{1}" },
