        // ---------------------------------------------------------------- diagnóstico
        ["diag.gogAch"] = new[] { "Versión de GOG con logros (trae Galaxy SDK). Se registran en tu cuenta de GOG si juegas con GOG Galaxy (o Heroic + Comet) abierto. Hydra no lee logros de GOG.", "GOG version with achievements (includes the Galaxy SDK). They are recorded on your GOG account if you play with GOG Galaxy (or Heroic + Comet) running. Hydra doesn't read GOG achievements.", "Versão GOG com conquistas (inclui o Galaxy SDK). Elas são registradas na sua conta GOG se você jogar com o GOG Galaxy (ou Heroic + Comet) aberto. O Hydra não lê conquistas da GOG.", "Version GOG avec succès (inclut le Galaxy SDK). Ils sont enregistrés sur votre compte GOG si vous jouez avec GOG Galaxy (ou Heroic + Comet) ouvert. Hydra ne lit pas les succès GOG.", "GOG-Version mit Erfolgen (enthält das Galaxy SDK). Sie werden in deinem GOG-Konto erfasst, wenn du mit geöffnetem GOG Galaxy (oder Heroic + Comet) spielst. Hydra liest keine GOG-Erfolge.", "Версия GOG с достижениями (есть Galaxy SDK). Они записываются в ваш аккаунт GOG, если играть с запущенным GOG Galaxy (или Heroic + Comet). Hydra не читает достижения GOG.", "带成就的 GOG 版本（包含 Galaxy SDK）。在运行 GOG Galaxy（或 Heroic + Comet）时游玩，成就会记录到你的 GOG 账户。Hydra 不读取 GOG 成就。", "実績付きの GOG 版です（Galaxy SDK を含む）。GOG Galaxy（または Heroic + Comet）を起動してプレイすると GOG アカウントに記録されます。Hydra は GOG の実績を読み取りません。" },
        ["diag.gogNo"] = new[] { "Versión de GOG sin Galaxy SDK: esta versión no registra logros en ningún sitio.", "GOG version without the Galaxy SDK: this version doesn't record achievements anywhere.", "Versão GOG sem o Galaxy SDK: esta versão não registra conquistas em lugar nenhum.", "Version GOG sans Galaxy SDK : cette version n'enregistre les succès nulle part.", "GOG-Version ohne Galaxy SDK: Diese Version erfasst nirgends Erfolge.", "Версия GOG без Galaxy SDK: эта версия нигде не записывает достижения.", "不含 Galaxy SDK 的 GOG 版本：此版本不会在任何地方记录成就。", "Galaxy SDK のない GOG 版です。このバージョンはどこにも実績を記録しません。" },
        ["diag.epic"] = new[] { "Usa Epic Online Services: sus logros van a una cuenta de Epic. Hydra no lee logros de Epic.", "Uses Epic Online Services: its achievements go to an Epic account. Hydra doesn't read Epic achievements.", "Usa o Epic Online Services: as conquistas vão para uma conta Epic. O Hydra não lê conquistas da Epic.", "Utilise Epic Online Services : ses succès vont sur un compte Epic. Hydra ne lit pas les succès Epic.", "Nutzt Epic Online Services: Die Erfolge landen in einem Epic-Konto. Hydra liest keine Epic-Erfolge.", "Использует Epic Online Services: достижения идут в аккаунт Epic. Hydra не читает достижения Epic.", "使用 Epic Online Services：成就会记录到 Epic 账户。Hydra 不读取 Epic 成就。", "Epic Online Services を使用：実績は Epic アカウントに記録されます。Hydra は Epic の実績を読み取りません。" },
        ["diag.ubi"] = new[] { "Usa Ubisoft Connect: sus logros van a una cuenta de Ubisoft. Hydra no los lee.", "Uses Ubisoft Connect: its achievements go to a Ubisoft account. Hydra doesn't read them.", "Usa o Ubisoft Connect: as conquistas vão para uma conta Ubisoft. O Hydra não as lê.", "Utilise Ubisoft Connect : ses succès vont sur un compte Ubisoft. Hydra ne les lit pas.", "Nutzt Ubisoft Connect: Die Erfolge landen in einem Ubisoft-Konto. Hydra liest sie nicht.", "Использует Ubisoft Connect: достижения идут в аккаунт Ubisoft. Hydra их не читает.", "使用 Ubisoft Connect：成就会记录到 Ubisoft 账户。Hydra 不读取这些成就。", "Ubisoft Connect を使用：実績は Ubisoft アカウントに記録されます。Hydra は読み取りません。" },
        ["diag.xbox"] = new[] { "Versión de Microsoft Store / Game Pass: sus logros van a tu cuenta de Xbox. Hydra no los lee.", "Microsoft Store / Game Pass version: its achievements go to your Xbox account. Hydra doesn't read them.", "Versão Microsoft Store / Game Pass: as conquistas vão para sua conta Xbox. O Hydra não as lê.", "Version Microsoft Store / Game Pass : ses succès vont sur votre compte Xbox. Hydra ne les lit pas.", "Microsoft-Store-/Game-Pass-Version: Die Erfolge landen in deinem Xbox-Konto. Hydra liest sie nicht.", "Версия Microsoft Store / Game Pass: достижения идут в ваш аккаунт Xbox. Hydra их не читает.", "Microsoft Store / Game Pass 版本：成就会记录到你的 Xbox 账户。Hydra 不读取这些成就。", "Microsoft Store / Game Pass 版：実績は Xbox アカウントに記録されます。Hydra は読み取りません。" },
        ["diag.none"] = new[] { "No usa ninguna plataforma de logros (ni Steam, ni GOG Galaxy, ni Epic…): esta versión del juego no tiene logros que seguir.", "Doesn't use any achievement platform (not Steam, GOG Galaxy, Epic…): this version of the game has no achievements to track.", "Não usa nenhuma plataforma de conquistas (nem Steam, GOG Galaxy, Epic…): esta versão do jogo não tem conquistas para acompanhar.", "N'utilise aucune plateforme de succès (ni Steam, ni GOG Galaxy, ni Epic…) : cette version du jeu n'a pas de succès à suivre.", "Nutzt keine Erfolgsplattform (weder Steam noch GOG Galaxy noch Epic…): Diese Spielversion hat keine Erfolge zum Verfolgen.", "Не использует платформ достижений (ни Steam, ни GOG Galaxy, ни Epic…): в этой версии игры нет достижений.", "未使用任何成就平台（Steam、GOG Galaxy、Epic 等均无）：此版本游戏没有可追踪的成就。", "実績プラットフォーム（Steam、GOG Galaxy、Epic など）を使用していません。このバージョンには追跡できる実績がありません。" },
        ["diag.signedOther"] = new[] { "steam_api.dll está firmada por \"{0}\", no por Valve, y no contiene firmas de emuladores conocidos.", "steam_api.dll is signed by \"{0}\", not Valve, and contains no known emulator signatures.", "A steam_api.dll é assinada por \"{0}\", não pela Valve, e não contém assinaturas de emuladores conhecidos.", "steam_api.dll est signée par « {0} », pas par Valve, et ne contient aucune signature d'émulateur connu.", "steam_api.dll ist von „{0}“ signiert, nicht von Valve, und enthält keine bekannten Emulator-Signaturen.", "steam_api.dll подписана «{0}», а не Valve, и не содержит сигнатур известных эмуляторов.", "steam_api.dll 由“{0}”签名而非 Valve，且不包含已知模拟器的特征。", "steam_api.dll は Valve ではなく「{0}」の署名で、既知のエミュレーターの特徴も含みません。" },
        ["diag.valveModified"] = new[] { "steam_api.dll dice ser de Valve pero su firma no es válida: el archivo original fue modificado (crack sin firmas reconocibles).", "steam_api.dll claims to be from Valve but its signature is invalid: the original file was modified (a crack with no recognizable signatures).", "A steam_api.dll diz ser da Valve, mas a assinatura é inválida: o arquivo original foi modificado (crack sem assinaturas reconhecíveis).", "steam_api.dll prétend venir de Valve mais sa signature est invalide : le fichier original a été modifié (crack sans signature reconnaissable).", "steam_api.dll gibt sich als Valve aus, aber die Signatur ist ungültig: Die Originaldatei wurde verändert (Crack ohne erkennbare Signaturen).", "steam_api.dll выдаёт себя за файл Valve, но подпись недействительна: оригинал изменён (кряк без узнаваемых сигнатур).", "steam_api.dll 声称来自 Valve，但签名无效：原始文件已被修改（无可识别特征的破解）。", "steam_api.dll は Valve 製を名乗っていますが署名が無効です。元のファイルが改変されています（識別できないクラック）。" },
        ["diag.unknownEmu"] = new[] { "steam_api.dll no está firmada por Valve y no contiene firmas de emuladores conocidos: probablemente es un emulador que no guarda logros.", "steam_api.dll isn't signed by Valve and contains no known emulator signatures: it's probably an emulator that doesn't save achievements.", "A steam_api.dll não é assinada pela Valve e não contém assinaturas de emuladores conhecidos: provavelmente é um emulador que não salva conquistas.", "steam_api.dll n'est pas signée par Valve et ne contient aucune signature d'émulateur connu : c'est sans doute un émulateur qui n'enregistre pas les succès.", "steam_api.dll ist nicht von Valve signiert und enthält keine bekannten Emulator-Signaturen: vermutlich ein Emulator, der keine Erfolge speichert.", "steam_api.dll не подписана Valve и не содержит сигнатур известных эмуляторов: вероятно, это эмулятор, который не сохраняет достижения.", "steam_api.dll 未经 Valve 签名，也不含已知模拟器的特征：可能是不保存成就的模拟器。", "steam_api.dll は Valve の署名がなく、既知のエミュレーターの特徴もありません。実績を保存しないエミュレーターと思われます。" },
        ["diag.options"] = new[] { "Opciones: si es un emulador que guarda logros en otro sitio, puede añadirse un puente; si no los guarda, la única vía es usar gbe_fork en este juego.", "Options: if it's an emulator that saves achievements elsewhere, a bridge can be added; if it doesn't save them, the only way is to use gbe_fork for this game.", "Opções: se for um emulador que salva conquistas em outro lugar, é possível adicionar uma ponte; se não salva, a única via é usar o gbe_fork neste jogo.", "Options : si c'est un émulateur qui enregistre les succès ailleurs, un pont peut être ajouté ; sinon, la seule solution est d'utiliser gbe_fork pour ce jeu.", "Optionen: Speichert der Emulator Erfolge woanders, kann eine Brücke ergänzt werden; speichert er keine, hilft nur gbe_fork für dieses Spiel.", "Варианты: если эмулятор сохраняет достижения в другом месте, можно добавить мост; если не сохраняет — остаётся только gbe_fork для этой игры.", "可选方案：如果模拟器把成就保存在其他位置，可以添加桥接；如果不保存，唯一的办法是为此游戏使用 gbe_fork。", "対処法：別の場所に実績を保存するエミュレーターならブリッジを追加できます。保存しない場合は、このゲームで gbe_fork を使うしかありません。" },
        ["diag.steamOriginal"] = new[] { "steam_api.dll es la original de Valve (firma verificada): es una copia de Steam.", "steam_api.dll is Valve's original (signature verified): this is a Steam copy.", "A steam_api.dll é a original da Valve (assinatura verificada): é uma cópia da Steam.", "steam_api.dll est l'original de Valve (signature vérifiée) : c'est une copie Steam.", "steam_api.dll ist das Original von Valve (Signatur geprüft): Das ist eine Steam-Kopie.", "steam_api.dll — оригинал Valve (подпись проверена): это копия из Steam.", "steam_api.dll 是 Valve 原版（签名已验证）：这是 Steam 副本。", "steam_api.dll は Valve の正規品です（署名確認済み）。Steam 版のゲームです。" },
        ["diag.steamReads"] = new[] { "Hydra lee sus logros directamente de tu cuenta de Steam.", "Hydra reads its achievements directly from your Steam account.", "O Hydra lê as conquistas diretamente da sua conta Steam.", "Hydra lit ses succès directement depuis votre compte Steam.", "Hydra liest die Erfolge direkt aus deinem Steam-Konto.", "Hydra читает достижения напрямую из вашего аккаунта Steam.", "Hydra 直接从你的 Steam 账户读取成就。", "Hydra は Steam アカウントから直接実績を読み取ります。" },
        ["diag.steamWill"] = new[] { "Hydra leerá los logros desde Steam si el juego está en tu cuenta y Steam está instalado en este PC.", "Hydra will read the achievements from Steam if the game is on your account and Steam is installed on this PC.", "O Hydra lerá as conquistas da Steam se o jogo estiver na sua conta e a Steam estiver instalada neste PC.", "Hydra lira les succès depuis Steam si le jeu est sur votre compte et que Steam est installé sur ce PC.", "Hydra liest die Erfolge aus Steam, wenn das Spiel in deinem Konto ist und Steam auf diesem PC installiert ist.", "Hydra прочитает достижения из Steam, если игра есть в вашем аккаунте и Steam установлен на этом ПК.", "如果游戏在你的账户中且本机已安装 Steam，Hydra 会从 Steam 读取成就。", "ゲームがアカウントにあり、この PC に Steam がインストールされていれば、Hydra は Steam から実績を読み取ります。" },
        ["diag.noAppId"] = new[] { "No se encontró el AppID de Steam. Haz clic derecho en el juego → \"{0}\".", "Steam AppID not found. Right-click the game → \"{0}\".", "AppID da Steam não encontrado. Clique com o botão direito no jogo → \"{0}\".", "AppID Steam introuvable. Clic droit sur le jeu → « {0} ».", "Steam-AppID nicht gefunden. Rechtsklick auf das Spiel → „{0}“.", "Steam AppID не найден. Щёлкните правой кнопкой по игре → «{0}».", "未找到 Steam AppID。右键点击游戏 →“{0}”。", "Steam AppID が見つかりません。ゲームを右クリック →「{0}」。" },
        ["diag.missingAch"] = new[] { "Usa Goldberg pero le falta steam_settings\\achievements.json: el juego no sabe qué logros existen y no los registrará.", "Uses Goldberg but steam_settings\\achievements.json is missing: the game doesn't know which achievements exist and won't record them.", "Usa Goldberg, mas falta o steam_settings\\achievements.json: o jogo não sabe quais conquistas existem e não vai registrá-las.", "Utilise Goldberg mais steam_settings\\achievements.json manque : le jeu ne sait pas quels succès existent et ne les enregistrera pas.", "Nutzt Goldberg, aber steam_settings\\achievements.json fehlt: Das Spiel kennt die Erfolge nicht und erfasst sie nicht.", "Использует Goldberg, но нет steam_settings\\achievements.json: игра не знает, какие достижения существуют, и не будет их записывать.", "使用 Goldberg，但缺少 steam_settings\\achievements.json：游戏不知道有哪些成就，因此不会记录。", "Goldberg を使用していますが steam_settings\\achievements.json がありません。ゲームは実績の一覧を知らないため記録しません。" },
        ["diag.missingAppIdFile"] = new[] { "Falta steam_settings\\steam_appid.txt.", "steam_settings\\steam_appid.txt is missing.", "Falta o steam_settings\\steam_appid.txt.", "steam_settings\\steam_appid.txt manque.", "steam_settings\\steam_appid.txt fehlt.", "Нет файла steam_settings\\steam_appid.txt.", "缺少 steam_settings\\steam_appid.txt。", "steam_settings\\steam_appid.txt がありません。" },
