        // ---------------------------------------------------------------- guía para juegos NO SOPORTADO
        ["menu.guide"] = new[] { "Guía para seguir sus logros…", "Guide to track its achievements…", "Guia para acompanhar as conquistas…", "Guide pour suivre ses succès…", "Anleitung zum Verfolgen der Erfolge…", "Как отслеживать достижения…", "成就追踪指南…", "実績を追跡するためのガイド…" },
        ["guide.onlyUnsupported"] = new[] { "La guía solo está disponible para juegos NO SOPORTADO.", "The guide is only available for UNSUPPORTED games.", "O guia só está disponível para jogos NÃO SUPORTADOS.", "Le guide n'est disponible que pour les jeux NON PRIS EN CHARGE.", "Die Anleitung ist nur für NICHT UNTERSTÜTZTE Spiele verfügbar.", "Инструкция доступна только для НЕ ПОДДЕРЖИВАЕМЫХ игр.", "该指南仅适用于“不支持”的游戏。", "ガイドは「非対応」のゲームでのみ利用できます。" },
        ["guide.title"] = new[] { "Seguir los logros de {0}", "Track the achievements of {0}", "Acompanhar as conquistas de {0}", "Suivre les succès de {0}", "Erfolge von {0} verfolgen", "Отслеживание достижений {0}", "追踪 {0} 的成就", "{0} の実績を追跡" },
        ["guide.intro"] = new[] { "Este juego usa un emulador que no guarda logros donde Hydra los busca. La app no instala emuladores, pero te ayuda a hacerlo tú de forma segura:", "This game uses an emulator that doesn't save achievements where Hydra looks for them. The app doesn't install emulators, but it helps you do it yourself safely:", "Este jogo usa um emulador que não salva conquistas onde o Hydra procura. O app não instala emuladores, mas ajuda você a fazer isso com segurança:", "Ce jeu utilise un émulateur qui n'enregistre pas les succès là où Hydra les cherche. L'app n'installe pas d'émulateurs, mais vous aide à le faire vous-même en toute sécurité :", "Dieses Spiel nutzt einen Emulator, der Erfolge nicht dort speichert, wo Hydra sucht. Die App installiert keine Emulatoren, hilft dir aber, es selbst sicher zu tun:", "Эта игра использует эмулятор, который не сохраняет достижения там, где их ищет Hydra. Приложение не устанавливает эмуляторы, но помогает безопасно сделать это самому:", "此游戏使用的模拟器不会把成就保存到 Hydra 查找的位置。本应用不会安装模拟器，但可以帮助你安全地自行操作：", "このゲームのエミュレーターは、Hydra が探す場所に実績を保存しません。アプリはエミュレーターをインストールしませんが、自分で安全に行えるよう手助けします：" },
        ["guide.step1"] = new[] { "1. Haz una copia de seguridad de la DLL actual (se guarda junto a ella como .hydralogros-original; no se toca nada más).", "1. Back up the current DLL (saved next to it as .hydralogros-original; nothing else is touched).", "1. Faça um backup da DLL atual (salvo ao lado dela como .hydralogros-original; nada mais é alterado).", "1. Sauvegardez la DLL actuelle (copiée à côté sous .hydralogros-original ; rien d'autre n'est modifié).", "1. Sichere die aktuelle DLL (wird daneben als .hydralogros-original gespeichert; sonst wird nichts verändert).", "1. Сделайте резервную копию текущей DLL (сохраняется рядом как .hydralogros-original; больше ничего не меняется).", "1. 备份当前的 DLL（以 .hydralogros-original 保存在旁边，不会改动其他任何内容）。", "1. 現在の DLL をバックアップします（同じ場所に .hydralogros-original として保存。他には何も変更しません）。" },
        ["guide.step2"] = new[] { "2. Descarga gbe_fork desde su repositorio oficial y lee sus instrucciones.", "2. Download gbe_fork from its official repository and read its instructions.", "2. Baixe o gbe_fork do repositório oficial e leia as instruções.", "2. Téléchargez gbe_fork depuis son dépôt officiel et lisez ses instructions.", "2. Lade gbe_fork aus dem offiziellen Repository herunter und lies die Anleitung.", "2. Скачайте gbe_fork из официального репозитория и прочитайте инструкцию.", "2. 从官方仓库下载 gbe_fork 并阅读其说明。", "2. 公式リポジトリから gbe_fork をダウンロードし、説明を読んでください。" },
        ["guide.step3"] = new[] { "3. Sustituye tú mismo steam_api.dll / steam_api64.dll en la carpeta del juego por la de gbe_fork.", "3. Replace steam_api.dll / steam_api64.dll in the game folder with gbe_fork's yourself.", "3. Substitua você mesmo a steam_api.dll / steam_api64.dll na pasta do jogo pela do gbe_fork.", "3. Remplacez vous-même steam_api.dll / steam_api64.dll dans le dossier du jeu par celle de gbe_fork.", "3. Ersetze steam_api.dll / steam_api64.dll im Spielordner selbst durch die von gbe_fork.", "3. Сами замените steam_api.dll / steam_api64.dll в папке игры на файл из gbe_fork.", "3. 自行将游戏文件夹中的 steam_api.dll / steam_api64.dll 替换为 gbe_fork 的版本。", "3. ゲームフォルダーの steam_api.dll / steam_api64.dll を、自分で gbe_fork のものに置き換えます。" },
        ["guide.step4"] = new[] { "4. Pulsa \"Comprobar\": si la app detecta gbe_fork, prepara la lista de logros y Hydra empezará a registrarlos.", "4. Click \"Check\": if the app detects gbe_fork, it prepares the achievement list and Hydra will start recording them.", "4. Clique em \"Verificar\": se o app detectar o gbe_fork, ele prepara a lista de conquistas e o Hydra começará a registrá-las.", "4. Cliquez sur « Vérifier » : si l'app détecte gbe_fork, elle prépare la liste des succès et Hydra commencera à les enregistrer.", "4. Klicke auf „Prüfen“: Erkennt die App gbe_fork, bereitet sie die Erfolgsliste vor und Hydra beginnt, Erfolge zu erfassen.", "4. Нажмите «Проверить»: если приложение обнаружит gbe_fork, оно подготовит список достижений, и Hydra начнёт их записывать.", "4. 点击“检查”：如果应用检测到 gbe_fork，会准备成就列表，Hydra 将开始记录成就。", "4. 「確認」を押します。アプリが gbe_fork を検出すると実績リストを準備し、Hydra が記録を始めます。" },
        ["guide.note"] = new[] { "Solo se ofrece para copias cuya DLL ya no es la original de Valve. La app nunca descarga, copia ni coloca el emulador.", "Only offered for copies whose DLL is no longer Valve's original. The app never downloads, copies or places the emulator.", "Oferecido apenas para cópias cuja DLL já não é a original da Valve. O app nunca baixa, copia nem coloca o emulador.", "Proposé uniquement pour les copies dont la DLL n'est plus l'originale de Valve. L'app ne télécharge, ne copie ni ne place jamais l'émulateur.", "Nur für Kopien, deren DLL nicht mehr das Original von Valve ist. Die App lädt, kopiert oder platziert den Emulator nie.", "Предлагается только для копий, где DLL уже не оригинальная от Valve. Приложение никогда не скачивает, не копирует и не размещает эмулятор.", "仅适用于 DLL 已不是 Valve 原版的副本。本应用从不下载、复制或放置模拟器。", "DLL がすでに Valve の正規品でないコピーにのみ表示されます。アプリがエミュレーターをダウンロード、コピー、配置することはありません。" },
        ["guide.backup"] = new[] { "Copia de seguridad de la DLL", "Back up the DLL", "Fazer backup da DLL", "Sauvegarder la DLL", "DLL sichern", "Резервная копия DLL", "备份 DLL", "DLL をバックアップ" },
