        ["guide.openFolder"] = new[] { "Abrir carpeta de la DLL", "Open DLL folder", "Abrir pasta da DLL", "Ouvrir le dossier de la DLL", "DLL-Ordner öffnen", "Открыть папку DLL", "打开 DLL 所在文件夹", "DLL のフォルダーを開く" },
