        ["guide.backupExists"] = new[] { "Ya existe una copia: {0} (no se toca).", "A backup already exists: {0} (left untouched).", "Já existe um backup: {0} (não é alterado).", "Une copie existe déjà : {0} (rien n'est modifié).", "Es gibt bereits eine Sicherung: {0} (bleibt unverändert).", "Копия уже есть: {0} (не трогаю).", "备份已存在：{0}（保持原样）。", "バックアップはすでにあります：{0}（変更しません）。" },
