        ["guide.stillUnsupported"] = new[] { "Todavía no se detecta gbe_fork. ¿Sustituiste la DLL correcta (la que está junto al ejecutable del juego)?", "gbe_fork isn't detected yet. Did you replace the right DLL (the one next to the game's executable)?", "O gbe_fork ainda não foi detectado. Você substituiu a DLL certa (a que fica ao lado do executável do jogo)?", "gbe_fork n'est pas encore détecté. Avez-vous remplacé la bonne DLL (celle à côté de l'exécutable du jeu) ?", "gbe_fork wird noch nicht erkannt. Hast du die richtige DLL ersetzt (die neben der Spiel-EXE)?", "gbe_fork пока не обнаружен. Вы заменили нужную DLL (рядом с исполняемым файлом игры)?", "尚未检测到 gbe_fork。你替换的是正确的 DLL（游戏可执行文件旁边的那个）吗？", "まだ gbe_fork が検出されません。正しい DLL（ゲームの実行ファイルの横にあるもの）を置き換えましたか？" },
        ["guide.detected"] = new[] { "¡gbe_fork detectado! Preparando el juego…", "gbe_fork detected! Preparing the game…", "gbe_fork detectado! Preparando o jogo…", "gbe_fork détecté ! Préparation du jeu…", "gbe_fork erkannt! Das Spiel wird vorbereitet…", "gbe_fork обнаружен! Подготавливаю игру…", "已检测到 gbe_fork！正在准备游戏…", "gbe_fork を検出しました！ゲームを準備しています…" },

