        ["sec.libSystem"] = new[] { "No se puede usar \"{0}\" como biblioteca: es una carpeta del sistema, de tu perfil o la raíz de un disco. Elige la carpeta donde están los juegos (por ejemplo D:\\Games).", "\"{0}\" can't be used as a library: it's a system folder, your profile folder or a drive root. Choose the folder that contains your games (for example D:\\Games).", "\"{0}\" não pode ser usada como biblioteca: é uma pasta do sistema, do seu perfil ou a raiz de um disco. Escolha a pasta onde estão os jogos (por exemplo D:\\Games).", "« {0} » ne peut pas servir de bibliothèque : c'est un dossier système, de votre profil ou la racine d'un disque. Choisissez le dossier qui contient vos jeux (par exemple D:\\Games).", "„{0}“ kann nicht als Bibliothek verwendet werden: Es ist ein System- oder Profilordner oder das Stammverzeichnis eines Laufwerks. Wähle den Ordner mit deinen Spielen (z. B. D:\\Games).", "«{0}» нельзя использовать как библиотеку: это системная папка, папка профиля или корень диска. Выберите папку с играми (например, D:\\Games).", "无法将“{0}”用作游戏库：它是系统文件夹、个人资料文件夹或磁盘根目录。请选择存放游戏的文件夹（例如 D:\\Games）。", "「{0}」はライブラリに使えません。システムフォルダー、プロファイルフォルダー、またはドライブのルートです。ゲームが入っているフォルダー（例：D:\\Games）を選んでください。" },
        ["sec.libLink"] = new[] { "No se puede usar \"{0}\" como biblioteca: es (o pasa por) un enlace simbólico. Elige la carpeta real.", "\"{0}\" can't be used as a library: it is (or goes through) a symbolic link. Choose the real folder.", "\"{0}\" não pode ser usada como biblioteca: é (ou passa por) um link simbólico. Escolha a pasta real.", "« {0} » ne peut pas servir de bibliothèque : c'est (ou passe par) un lien symbolique. Choisissez le vrai dossier.", "„{0}“ kann nicht als Bibliothek verwendet werden: Es ist (oder führt über) eine symbolische Verknüpfung. Wähle den echten Ordner.", "«{0}» нельзя использовать как библиотеку: это символическая ссылка (или путь проходит через неё). Выберите настоящую папку.", "无法将“{0}”用作游戏库：它是（或经过）符号链接。请选择实际文件夹。", "「{0}」はライブラリに使えません。シンボリックリンク（またはそれを経由するパス）です。実際のフォルダーを選んでください。" },
        ["sec.writeBlocked"] = new[] { "Bloqueado por seguridad: la app no escribe en {0} (no es un archivo que la app gestione, está fuera de tus bibliotecas o pasa por un enlace simbólico).", "Blocked for security: the app doesn't write to {0} (it's not a file the app manages, it's outside your libraries or it goes through a symbolic link).", "Bloqueado por segurança: o app não grava em {0} (não é um arquivo que o app gerencia, está fora das suas bibliotecas ou passa por um link simbólico).", "Bloqué par sécurité : l'app n'écrit pas dans {0} (ce n'est pas un fichier géré par l'app, il est hors de vos bibliothèques ou passe par un lien symbolique).", "Aus Sicherheitsgründen blockiert: Die App schreibt nicht nach {0} (keine von der App verwaltete Datei, außerhalb deiner Bibliotheken oder über eine symbolische Verknüpfung).", "Заблокировано из соображений безопасности: приложение не пишет в {0} (это не его файл, путь вне ваших библиотек или проходит через символическую ссылку).", "出于安全原因已阻止：应用不会写入 {0}（它不是应用管理的文件、不在你的游戏库中，或经过符号链接）。", "セキュリティのためブロック：アプリは {0} に書き込みません（アプリが管理するファイルではない、ライブラリの外、またはシンボリックリンクを経由しています）。" },
        ["sec.undoSuspicious"] = new[] { "Se omite una entrada de cambios.json: {0} no es un archivo que la app pueda haber creado o está fuera de tus bibliotecas actuales. No se toca.", "Skipping a cambios.json entry: {0} isn't a file the app could have created, or it's outside your current libraries. Left untouched.", "Ignorando uma entrada do cambios.json: {0} não é um arquivo que o app possa ter criado ou está fora das suas bibliotecas atuais. Não é alterado.", "Entrée de cambios.json ignorée : {0} n'est pas un fichier que l'app a pu créer, ou il est hors de vos bibliothèques actuelles. Rien n'est modifié.", "Eintrag in cambios.json übersprungen: {0} ist keine Datei, die die App erstellt haben kann, oder liegt außerhalb deiner aktuellen Bibliotheken. Bleibt unverändert.", "Пропущена запись cambios.json: {0} не мог быть создан приложением или находится вне текущих библиотек. Не трогаю.", "已跳过 cambios.json 中的一项：{0} 不是应用可能创建的文件，或不在当前游戏库中。保持原样。", "cambios.json の項目をスキップ：{0} はアプリが作成し得るファイルではないか、現在のライブラリの外にあります。変更しません。" },
        ["sec.appIdInvalid"] = new[] { "Se ignora el AppID manual de \"{0}\" en config.json: no es un número válido.", "Ignoring the manual AppID for \"{0}\" in config.json: it isn't a valid number.", "Ignorando o AppID manual de \"{0}\" no config.json: não é um número válido.", "AppID manuel de « {0} » ignoré dans config.json : ce n'est pas un nombre valide.", "Manuelle AppID für „{0}“ in config.json wird ignoriert: keine gültige Zahl.", "Ручной AppID для «{0}» в config.json пропущен: это не число.", "已忽略 config.json 中“{0}”的手动 AppID：不是有效数字。", "config.json の「{0}」の手動 AppID を無視します：有効な数字ではありません。" },
        ["sec.admin"] = new[] { "La app se está ejecutando como administrador. No hace falta: ábrela normalmente para mayor seguridad.", "The app is running as administrator. That isn't needed: open it normally for better security.", "O app está sendo executado como administrador. Não é necessário: abra-o normalmente para mais segurança.", "L'app s'exécute en tant qu'administrateur. Ce n'est pas nécessaire : ouvrez-la normalement pour plus de sécurité.", "Die App läuft als Administrator. Das ist nicht nötig: Öffne sie normal, das ist sicherer.", "Приложение запущено от имени администратора. Это не нужно: для безопасности запускайте его обычным способом.", "应用正以管理员身份运行。这没有必要：为安全起见，请正常打开。", "アプリが管理者として実行されています。その必要はありません。安全のため通常どおり起動してください。" },
        ["sec.urlBlocked"] = new[] { "Bloqueado: la app solo abre direcciones web de confianza.", "Blocked: the app only opens trusted web addresses.", "Bloqueado: o app só abre endereços web confiáveis.", "Bloqué : l'app n'ouvre que des adresses web de confiance.", "Blockiert: Die App öffnet nur vertrauenswürdige Webadressen.", "Заблокировано: приложение открывает только доверенные веб-адреса.", "已阻止：应用只打开受信任的网址。", "ブロック：アプリは信頼できる Web アドレスのみ開きます。" },
        ["sec.netBlocked"] = new[] { "Bloqueado: la app solo se conecta a la API oficial de Steam por HTTPS.", "Blocked: the app only connects to the official Steam API over HTTPS.", "Bloqueado: o app só se conecta à API oficial da Steam via HTTPS.", "Bloqué : l'app ne se connecte qu'à l'API officielle de Steam en HTTPS.", "Blockiert: Die App verbindet sich nur per HTTPS mit der offiziellen Steam-API.", "Заблокировано: приложение подключается только к официальному Steam API по HTTPS.", "已阻止：应用只通过 HTTPS 连接 Steam 官方 API。", "ブロック：アプリは HTTPS で公式 Steam API にのみ接続します。" },
        ["steam.redirect"] = new[] { "Steam respondió con una redirección inesperada; por seguridad no se sigue (tu clave no se envía a otro sitio).", "Steam answered with an unexpected redirect; for security it isn't followed (your key isn't sent anywhere else).", "A Steam respondeu com um redirecionamento inesperado; por segurança ele não é seguido (sua chave não é enviada a outro lugar).", "Steam a répondu par une redirection inattendue ; par sécurité elle n'est pas suivie (votre clé n'est envoyée nulle part ailleurs).", "Steam hat mit einer unerwarteten Weiterleitung geantwortet; aus Sicherheitsgründen wird ihr nicht gefolgt (dein Schlüssel wird nirgendwo anders hingeschickt).", "Steam ответил неожиданным перенаправлением; из соображений безопасности оно не выполняется (ключ никуда больше не отправляется).", "Steam 返回了意外的重定向；出于安全考虑不会跟随（你的密钥不会被发送到其他地方）。", "Steam から予期しないリダイレクトが返されました。安全のため従いません（キーが他所に送られることはありません）。" },
